<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { eliminarResultado, guardarResultado, listarResultados } from '../services/resultados'
import type { MuestraResultado, ParametroResultado, ResultadoCalidad, ResultadoPayload } from '../interfaces/resultados.interface'
const records=ref<ResultadoCalidad[]>([]),samples=ref<MuestraResultado[]>([]),parameters=ref<ParametroResultado[]>([]),selected=ref<ResultadoCalidad|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),filters=reactive({fecha_desde:'',fecha_hasta:'',parametros:[] as number[],muestra_id:''}),form=reactive<ResultadoPayload>({muestra_id:null,parametro_id:null,valor:null})
const selectedParameter=computed(()=>parameters.value.find(x=>x.id===form.parametro_id))
async function load(target=1){loading.value=true;error.value='';try{const r=await listarResultados({...filters,page:target});records.value=r.data;samples.value=r.muestras;parameters.value=r.parametros;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{fecha_desde:'',fecha_hasta:'',parametros:[],muestra_id:''});load(1)}
function open(item?:ResultadoCalidad){editing.value=item?.id??null;Object.assign(form,item?{muestra_id:item.muestra_id,parametro_id:item.parametro_id,valor:item.valor}:{muestra_id:filters.muestra_id?Number(filters.muestra_id):null,parametro_id:null,valor:null});modal.value=true}
async function save(){if(!form.muestra_id||!form.parametro_id||form.valor==null){error.value='Seleccione la muestra, el parámetro e ingrese el valor.';return}saving.value=true;error.value='';try{await guardarResultado(form,editing.value??undefined);modal.value=false;success.value=`Resultado ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:ResultadoCalidad){if(!confirm(`¿Eliminar el resultado #${item.id}?`))return;try{await eliminarResultado(item.id);success.value='Resultado eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const number=(v:number)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:6}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Control de Calidad / Resultados</nav><header class="hero"><div class="mark">RC</div><div><small>DANA · CONTROL DE CALIDAD</small><h1>Resultados de muestras</h1><p>Registra y consulta las mediciones obtenidas por parámetro.</p></div><button @click="open()">+ Nuevo resultado</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><label>Muestra<select v-model="filters.muestra_id"><option value="">Todas</option><option v-for="item in samples" :key="item.id" :value="item.id">{{item.etiqueta}}</option></select></label><label>Parámetros<select v-model="filters.parametros" multiple size="2"><option v-for="item in parameters" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><div><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><section class="summary"><article><small>RESULTADOS ENCONTRADOS</small><b>{{total}}</b></article><article><small>MUESTRAS DISPONIBLES</small><b>{{samples.length}}</b></article><article><small>PARÁMETROS EVALUADOS</small><b>{{new Set(records.map(x=>x.parametro_id)).size}}</b></article></section><div v-if="loading" class="empty">Cargando resultados…</div><div v-else-if="!records.length" class="empty">No hay resultados para los filtros seleccionados.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><span>∿</span><div><small>RESULTADO #{{item.id}}</small><h2>{{item.parametro}}</h2></div><em>{{item.codigo}}</em></header><div class="measure"><b>{{number(item.valor)}}</b><span>{{item.unidad}}</span></div><dl><div><dt>Muestra</dt><dd>{{item.muestra}}</dd></div><div><dt>Componente</dt><dd>{{item.componente}}</dd></div><div><dt>Fecha y hora</dt><dd>{{item.created_at}}</dd></div></dl><footer><button class="view" @click="selected=item">Ver</button><button class="edit" @click="open(item)">Modificar</button><button class="delete" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="detail"><header><div><small>LECTURA ANALÍTICA</small><h2>Resultado #{{selected.id}}</h2></div><button @click="selected=null">×</button></header><div class="big-value"><b>{{number(selected.valor)}}</b><span>{{selected.unidad}}</span></div><dl><div><dt>Muestra</dt><dd>{{selected.muestra}}</dd></div><div><dt>Componente</dt><dd>{{selected.componente}}</dd></div><div><dt>Parámetro</dt><dd>{{selected.parametro}}</dd></div><div><dt>Código</dt><dd>{{selected.codigo}}</dd></div><div><dt>Registrado</dt><dd>{{selected.created_at}}</dd></div></dl></section></div><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>CONTROL DE CALIDAD</small><h2>{{editing?'Modificar':'Registrar'}} resultado</h2></div><button type="button" @click="modal=false">×</button></header><label>Muestra *<select v-model="form.muestra_id" required><option :value="null">Buscar muestra</option><option v-for="item in samples" :key="item.id" :value="item.id">{{item.etiqueta}}</option></select></label><label>Parámetro *<select v-model="form.parametro_id" required><option :value="null">Seleccione</option><option v-for="item in parameters" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><div class="value-row"><label>Valor *<input v-model.number="form.valor" type="number" step="any" required></label><label>Unidad<input :value="selectedParameter?.unidad||''" disabled placeholder="—"></label></div><p>Solo puede existir un resultado por cada combinación de muestra y parámetro.</p><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
